CREATE DATABASE IF NOT EXISTS `learning_journey` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `learning_journey`;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS student_chapter_progress,subject_chapters,portfolio,achievements,archive,careerPlans,universityPlans,tka,futurePlans,feedback,assessments,goals,reflections,competencies,users,students,teachers,subjects,classes;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE classes(id VARCHAR(50) PRIMARY KEY,name VARCHAR(80) NOT NULL,grade INT NOT NULL,stage VARCHAR(80),status VARCHAR(30) DEFAULT 'Aktif');
CREATE TABLE users(id VARCHAR(50) PRIMARY KEY,username VARCHAR(100) UNIQUE,password VARCHAR(255),name VARCHAR(150),role ENUM('student','teacher'),studentId VARCHAR(50),teacherId VARCHAR(50));
CREATE TABLE teachers(id VARCHAR(50) PRIMARY KEY,name VARCHAR(150) NOT NULL,subject VARCHAR(100),status VARCHAR(40) DEFAULT 'Aktif',classId VARCHAR(50));
CREATE TABLE students(id VARCHAR(50) PRIMARY KEY,name VARCHAR(150) NOT NULL,nis VARCHAR(50),nisn VARCHAR(50),class VARCHAR(80),classId VARCHAR(50),grade INT DEFAULT 10,status VARCHAR(40) DEFAULT 'Aktif',avatar VARCHAR(10));
CREATE TABLE subjects(id VARCHAR(50) PRIMARY KEY,name VARCHAR(150) NOT NULL,category VARCHAR(100),grade VARCHAR(50),progress INT DEFAULT 0,icon VARCHAR(20));
CREATE TABLE subject_chapters(id VARCHAR(50) PRIMARY KEY,subjectId VARCHAR(50) NOT NULL,title VARCHAR(255),description TEXT,orderNo INT DEFAULT 1,FOREIGN KEY(subjectId) REFERENCES subjects(id) ON DELETE CASCADE);
CREATE TABLE student_chapter_progress(id VARCHAR(100) PRIMARY KEY,studentId VARCHAR(50) NOT NULL,chapterId VARCHAR(50) NOT NULL,progress INT DEFAULT 0,status VARCHAR(50) DEFAULT 'Belum Dimulai',note TEXT,lastUpdated DATE,UNIQUE KEY uq_student_chapter(studentId,chapterId),FOREIGN KEY(studentId) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(chapterId) REFERENCES subject_chapters(id) ON DELETE CASCADE);
CREATE TABLE reflections(id VARCHAR(50) PRIMARY KEY,studentId VARCHAR(50) NOT NULL,subject VARCHAR(150),topic VARCHAR(255),chapterId VARCHAR(50),learned TEXT,level VARCHAR(80),reason TEXT,nextAction TEXT,evidence TEXT,date DATE,INDEX(studentId));
CREATE TABLE competencies(id VARCHAR(50) PRIMARY KEY,name VARCHAR(150),category VARCHAR(100),progress INT DEFAULT 0,level VARCHAR(100));
CREATE TABLE goals(id VARCHAR(50) PRIMARY KEY,studentId VARCHAR(50),title VARCHAR(255),description TEXT,category VARCHAR(100),grade INT,targetDate DATE NULL,progress INT DEFAULT 0,status VARCHAR(80));
CREATE TABLE assessments(id VARCHAR(50) PRIMARY KEY,studentId VARCHAR(50),type VARCHAR(80),category VARCHAR(100),subject VARCHAR(150),grade INT,score DECIMAL(6,2),max DECIMAL(6,2),date DATE);
CREATE TABLE feedback(id VARCHAR(50) PRIMARY KEY,reflectionId VARCHAR(50),studentId VARCHAR(50),teacherId VARCHAR(50),teacher VARCHAR(150),comment TEXT,recommendation TEXT,date DATE,INDEX(studentId));
CREATE TABLE futurePlans(id VARCHAR(50) PRIMARY KEY,studentId VARCHAR(50),type VARCHAR(100),target VARCHAR(255),detail TEXT,year VARCHAR(20),status VARCHAR(80),notes TEXT);
CREATE TABLE tka(id VARCHAR(50) PRIMARY KEY,studentId VARCHAR(50),title VARCHAR(255),subject VARCHAR(150),date DATE,score DECIMAL(6,2) DEFAULT 0,status VARCHAR(80),notes TEXT);
CREATE TABLE universityPlans(id VARCHAR(50) PRIMARY KEY,studentId VARCHAR(50),title VARCHAR(255),institution VARCHAR(255),targetYear VARCHAR(20),status VARCHAR(80),notes TEXT,progress INT DEFAULT 0);
CREATE TABLE careerPlans(id VARCHAR(50) PRIMARY KEY,studentId VARCHAR(50),title VARCHAR(255),institution VARCHAR(255),targetYear VARCHAR(20),status VARCHAR(80),notes TEXT,progress INT DEFAULT 0);
CREATE TABLE archive(id VARCHAR(50) PRIMARY KEY,studentId VARCHAR(50),title VARCHAR(255),category VARCHAR(100),grade VARCHAR(20),description TEXT,link TEXT,date DATE);
CREATE TABLE achievements(id VARCHAR(50) PRIMARY KEY,name VARCHAR(150),description TEXT,icon VARCHAR(20),earned BOOLEAN DEFAULT FALSE,date DATE);
CREATE TABLE portfolio(id VARCHAR(50) PRIMARY KEY,studentId VARCHAR(50),title VARCHAR(255),category VARCHAR(100),description TEXT,link TEXT,file TEXT,date DATE,status VARCHAR(80));
